import { ChangeDetectionStrategy, Component, booleanAttribute, input, model } from '@angular/core';

export interface AevkoAccordionItem {
  id: string;
  label: string;
  content: string;
  disabled?: boolean;
}

@Component({
  selector: 'aevko-accordion',
  standalone: true,
  templateUrl: './accordion.component.html',
  styleUrl: './accordion.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class AevkoAccordion {
  readonly items = input.required<readonly AevkoAccordionItem[]>();
  readonly type = input<'single' | 'multiple'>('single');
  readonly value = model<readonly string[]>([]);
  readonly collapsible = input(true, { transform: booleanAttribute });
  readonly disabled = input(false, { transform: booleanAttribute });
  readonly id = input('aevko-accordion');
  readonly headingLevel = input<2 | 3 | 4 | 5 | 6>(2);

  protected expanded(item: AevkoAccordionItem): boolean {
    return this.value().includes(item.id);
  }
  protected toggle(item: AevkoAccordionItem): void {
    if (this.disabled() || item.disabled) return;
    const current = this.value();
    if (this.expanded(item)) {
      if (this.collapsible() || this.type() === 'multiple')
        this.value.set(current.filter((id) => id !== item.id));
      return;
    }
    this.value.set(this.type() === 'single' ? [item.id] : [...current, item.id]);
  }
}

:host {
  display: block;
}
section {
  border-bottom: 1px solid var(--aevko-border, #c7c7c7);
}
.heading {
  margin: 0;
}
button {
  align-items: center;
  background: transparent;
  border: 0;
  color: inherit;
  cursor: pointer;
  display: flex;
  font: 700 1rem/1.3 var(--aevko-font-sans, sans-serif);
  justify-content: space-between;
  min-height: 3rem;
  padding: 0.75rem 0;
  text-align: start;
  width: 100%;
}
button:focus-visible {
  outline: 2px solid var(--aevko-focus, #a1a1aa);
  outline-offset: 1px;
}
button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}
.indicator {
  align-items: center;
  display: inline-flex;
  flex: none;
  transition: transform 120ms ease;
}
.indicator.open {
  transform: rotate(90deg);
}
.indicator svg {
  height: 1rem;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 2;
  width: 1rem;
}
[role='region'] {
  display: grid;
  grid-template-rows: 1fr;
  opacity: 1;
  transition:
    grid-template-rows 180ms ease,
    opacity 180ms ease;
}
[role='region'][hidden] {
  display: none;
  grid-template-rows: 0fr;
  opacity: 0;
}
p {
  line-height: 1.5;
  margin: 0;
  padding: 0 0 1rem;
}
@media (prefers-reduced-motion: reduce) {
  .indicator,
  [role='region'] {
    transition: none;
  }
}
